//! `docs/corpus-coverage.md` is generated by `al-test-cli --coverage-map` (issue 52). Regenerating it on the
//! current corpus pin must give the committed file, so it stays current like the golden list of
//! `corpus_resolve_deps`. Regenerate with `./target/release/al-test-cli --root . --coverage-map`.

use std::path::{Path, PathBuf};

fn root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../..")
        .canonicalize()
        .unwrap()
}

#[test]
fn the_committed_coverage_map_is_current() {
    let root = root();
    let cfg =
        al_test_cli::config::OracleFile::parse(&std::fs::read_to_string(root.join("oracle/oracle.toml")).unwrap())
            .unwrap();
    let map = al_test_cli::coverage::corpus_coverage(&root).unwrap();
    let committed = std::fs::read_to_string(root.join("docs/corpus-coverage.md")).unwrap_or_default();
    assert!(
        committed == map.markdown(&cfg.corpus_commit),
        "docs/corpus-coverage.md is stale: run `al-test-cli --root . --coverage-map` and commit the result"
    );
    // The corpus calls a good part of the catalog, and every count adds up.
    assert!(
        map.pinned() > 300 && map.pinned() < map.total(),
        "{} of {}",
        map.pinned(),
        map.total()
    );
}
